using System;using System.IO;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Newtonsoft.Json;
public static class PRToolLog {
 public static object Read(){var a=typeof(Editor).Assembly;var t=a.GetType("UnityEditor.LogEntries");var et=a.GetType("UnityEditor.LogEntry");var flags=BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic;var list=new List<string>();int n=(int)t.GetMethod("StartGettingEntries",flags).Invoke(null,null);try{for(int i=0;i<Math.Min(n,6);i++){var entry=Activator.CreateInstance(et);t.GetMethod("GetEntryInternal",flags).Invoke(null,new object[]{i,entry});list.Add((string)et.GetField("message",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).GetValue(entry));}}finally{t.GetMethod("EndGettingEntries",flags).Invoke(null,null);}File.WriteAllText(Path.GetFullPath(Application.dataPath+"/../../../Docs/Review/2026-11-13_1F_PropRefinement/review_tool_diagnostic.json"),JsonConvert.SerializeObject(new{entries=n,sample=list},Formatting.Indented));return new{entries=n,sample=list};}
 public static object ClearOwn(){typeof(Editor).Assembly.GetType("UnityEditor.LogEntries").GetMethod("Clear",BindingFlags.Static|BindingFlags.Public).Invoke(null,null);return new{cleared=true};}
}
